#!/usr/bin/env python3
"""Generates src/cloud/mega/test_vectors.rs with an implementation that is
independent from the Rust code under test (Python + `cryptography`, written
from the megajs / mega-rs reference algorithms).

Usage: python3 -I generate_vectors.py > ../../../src/cloud/mega/test_vectors.rs
"""
import base64
import json
import sys

from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes


def b64(data: bytes) -> str:
    return base64.urlsafe_b64encode(data).decode().rstrip("=")


def ecb_enc(key, data):
    e = Cipher(algorithms.AES(key), modes.ECB()).encryptor()
    return e.update(data) + e.finalize()


def cbc_enc_zero_iv(key, data):
    e = Cipher(algorithms.AES(key), modes.CBC(bytes(16))).encryptor()
    return e.update(data) + e.finalize()


def ctr(key, nonce, data):
    # 16-byte counter block: 8-byte nonce followed by an 8-byte big-endian counter.
    e = Cipher(algorithms.AES(key), modes.CTR(nonce + bytes(8))).encryptor()
    return e.update(data) + e.finalize()


def pattern(length):
    return bytes((i * 31 + 7) & 0xFF for i in range(length))


def fold(raw32):
    return bytes(a ^ b for a, b in zip(raw32[:16], raw32[16:])), raw32[16:24], raw32[24:]


def meta_mac(aes_key, nonce, data):
    # Reference: mega-rs `compute_condensed_mac` -- chunks of 128 KiB growing by
    # 128 KiB up to 1 MiB, each chunk CBC-MACed from IV = nonce || nonce, the
    # chunk MACs chained through a zero-IV CBC, then folded to 8 bytes. A file
    # ending exactly on a chunk boundary has no trailing empty chunk.
    ecb = Cipher(algorithms.AES(aes_key), modes.ECB()).encryptor()
    chunk, off, final = 131072, 0, bytes(16)
    while off < len(data):
        part = data[off:off + chunk]
        padded = part + bytes((-len(part)) % 16)
        cbc = Cipher(algorithms.AES(aes_key), modes.CBC(nonce + nonce)).encryptor()
        cur = cbc.update(padded)[-16:]
        final = ecb.update(bytes(a ^ b for a, b in zip(final, cur)))
        off += len(part)
        chunk = min(chunk + 131072, 1048576)
    return bytes([final[0] ^ final[4], final[1] ^ final[5], final[2] ^ final[6], final[3] ^ final[7],
                  final[8] ^ final[12], final[9] ^ final[13], final[10] ^ final[14], final[11] ^ final[15]])


def attributes(name):
    raw = b"MEGA" + json.dumps({"n": name}, ensure_ascii=False, separators=(",", ":")).encode()
    return raw + bytes((-len(raw)) % 16)


def rust_bytes(data):
    return "&[" + ", ".join(f"0x{b:02x}" for b in data) + "]"


def main():
    out = ["// @generated by tests/fixtures/mega/generate_vectors.py -- do not edit.",
           "// Independent (Python `cryptography`) vectors for the MEGA primitives.", ""]

    # --- single file ---------------------------------------------------------
    aes_key = bytes((i * 13 + 5) & 0xFF for i in range(16))
    nonce = bytes((i * 19 + 2) & 0xFF for i in range(8))
    plain_small = pattern(5000)
    # MAC vectors: sizes around chunk boundaries (all derived from `pattern`).
    sizes = [1, 17, 16, 131072, 131073, 393216, 1048576 + 7, 3000000]
    macs = {n: meta_mac(aes_key, nonce, pattern(n)) for n in sizes}
    # The advertised key carries the MAC of the 131073-byte reference file:
    # k = (aes_key XOR (nonce || mac)) || nonce || mac.
    tail = nonce + macs[131073]
    full_key = bytes(a ^ b for a, b in zip(aes_key, tail)) + tail
    assert fold(full_key) == (aes_key, nonce, macs[131073])
    out.append(f"pub const FILE_KEY: [u8; 32] = {rust_bytes(full_key).replace('&', '')};")
    out.append(f"pub const FILE_KEY_B64: &str = \"{b64(full_key)}\";")
    out.append(f"pub const FILE_AES_KEY: [u8; 16] = {rust_bytes(aes_key).replace('&', '')};")
    out.append(f"pub const FILE_NONCE: [u8; 8] = {rust_bytes(nonce).replace('&', '')};")
    out.append(f"pub const PLAIN_LEN: usize = {len(plain_small)};")
    out.append(f"pub const CIPHERTEXT_HEX: &str = \"{ctr(aes_key, nonce, plain_small).hex()}\";")
    out.append("pub const MAC_VECTORS: &[(u64, [u8; 8])] = &[")
    for n in sizes:
        out.append(f"    ({n}, {rust_bytes(macs[n]).replace('&', '')}),")
    out.append("];")
    file_name = "Report éè final.pdf"
    out.append(f"pub const FILE_NAME: &str = \"{file_name}\";")
    out.append(f"pub const FILE_ATTR_B64: &str = \"{b64(cbc_enc_zero_iv(aes_key, attributes(file_name)))}\";")
    out.append("")

    # --- folder --------------------------------------------------------------
    folder_key = bytes((i * 29 + 11) & 0xFF for i in range(16))
    other_key = bytes((i * 3 + 1) & 0xFF for i in range(16))

    def node_keys(seed, is_file):
        raw = bytes((seed * 17 + i * 7 + 3) & 0xFF for i in range(32 if is_file else 16))
        return raw

    def folder_node(handle, parent, is_file, seed, name, size=None, share_key=folder_key):
        raw = node_keys(seed, is_file)
        attr_key = fold(raw)[0] if is_file else raw
        node = {
            "h": handle, "p": parent, "u": "OWNERHND", "t": 0 if is_file else 1,
            "a": b64(cbc_enc_zero_iv(attr_key, attributes(name))),
            "k": "OWNERHND:" + b64(ecb_enc(share_key, raw)), "ts": 1700000000,
        }
        if is_file:
            node["s"] = size
        return node, raw

    nodes = []
    expected = []
    root, _ = folder_node("ROOTHNDL", "", False, 1, "Shared фото")
    d2024, _ = folder_node("DIR2024H", "ROOTHNDL", False, 2, "2024")
    deep, _ = folder_node("DEEPDIRH", "DIR2024H", False, 3, "deep dir")
    f_a, raw_a = folder_node("FILEAAAA", "ROOTHNDL", True, 4, "a.bin", 10)
    f_b, raw_b = folder_node("FILEBBBB", "DIR2024H", True, 5, "b.txt", 20)
    f_c, raw_c = folder_node("FILECCCC", "DEEPDIRH", True, 6, "c.mp4", 4194305)
    stranger, _ = folder_node("FILEZZZZ", "ROOTHNDL", True, 7, "foreign.bin", 5, share_key=other_key)
    nodes = [root, d2024, deep, f_a, f_b, f_c, stranger]
    out.append(f"pub const FOLDER_KEY: [u8; 16] = {rust_bytes(folder_key).replace('&', '')};")
    out.append(f"pub const FOLDER_KEY_B64: &str = \"{b64(folder_key)}\";")
    out.append("pub const FOLDER_LISTING: &str = r####\"" + json.dumps({"f": nodes, "sn": "x"}, ensure_ascii=False) + "\"####;")
    for handle, raw in (("FILEAAAA", raw_a), ("FILEBBBB", raw_b), ("FILECCCC", raw_c)):
        out.append(f"pub const NODE_KEY_{handle}: [u8; 32] = {rust_bytes(raw).replace('&', '')};")
    sys.stdout.write("\n".join(out) + "\n")


if __name__ == "__main__":
    main()
